contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller provides depositor address (as msg.sender),
    // an initial deposit amount initAmt and a second deposit amount addAmt.
    // We require this contract has enough balance to send the two deposits.
    function check(address depositor, uint initAmt, uint addAmt) public {
        // preconditions to keep arithmetic simple and avoid overflow in P
        require(initAmt + addAmt >= initAmt);
        require(address(this).balance >= initAmt + addAmt);

        // first deposit: credit depositor with initAmt
        // must be performed by this contract sending ether on behalf of depositor.
        // We simulate depositor by using call from this contract but the contract C records balances by msg.sender,
        // so we need to invoke Deposit from this contract to affect c.balances(address(this)).
        // Therefore we use depositor parameter only for observation via public getter later.

        // Make first deposit from this contract
        c.Deposit{value: initAmt}();
        // read balance after first deposit
        uint balAfterFirst = c.balances(address(this));

        // second deposit from this contract
        c.Deposit{value: addAmt}();
        uint balAfterSecond = c.balances(address(this));

        // The invariant: the second balance must be at least balAfterFirst + addAmt (i.e., balances increased by addAmt)
        // This holds for original P (which adds msg.value) but is violated by mutant M (which resets to msg.value)
        assert(balAfterSecond >= balAfterFirst + addAmt);
    }

    // allow contract to be funded for making deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function performing the minimal sequence: ensure this contract has funds, call Deposit with amount, then assert recorded balance equals amount
    function runTest(uint initialFund, uint depositAmt) public {
        // preconditions for meaningful test
        require(initialFund >= depositAmt, "need initialFund >= depositAmt");
        // fund this test contract so it can forward Ether
        // caller must have sent initialFund to this contract before calling runTest in a real environment
        require(address(this).balance >= depositAmt, "contract balance insufficient for deposit");

        // record balance before
        uint before = c.balances(address(this));

        // perform the deposit on c forwarding depositAmt
        c.Deposit{value: depositAmt}();

        // read balance after
        uint after = c.balances(address(this));

        // the property: after - before == depositAmt
        assert(after - before == depositAmt);
    }

    // allow funding this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // call Deposit sending Ether 'amount'
        c.Deposit{value: amount}();
        // The general rule: the stored balance for this test contract equals the sent amount
        assert(c.balances(address(this)) == amount);
    }
    receive() external payable {}
}
